and I.GRADE_DATE =( select max(a.GRADE_DATE) from MST_BOND_CREDIT_RATING a where a.O_TYPE='01' and a.O_CODE= I.O_CODE and a.GRADE_DATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
) and I.GRADE_RESULT = ( select max(GRADE_RESULT) from MST_BOND_CREDIT_RATING where O_TYPE='01' and O_CODE= I.O_CODE and GRADE_DATE = I.GRADE_DATE )
) GRADE_RESULT FROM FIN_DEAL_PLEDGE A LEFT JOIN TRD_PRODUCT_DEAL B ON A.FINPROD_ID = B.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE C ON A.PLEDGE_FINPROD_ID = C.FINPROD_ID LEFT JOIN FIN_PRODUCT D ON A.PLEDGE_FINPROD_ID = D.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO_ADD E ON E.CUSTOMER_ID = D.ISSUER LEFT JOIN FIN_PRODUCT_ADD F ON A.PLEDGE_FINPROD_ID = F.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD G ON G.TRADE_ID = B.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD fpa ON G.PORTFOLIO_ID=fpa.PORTFOLIO_ID /*修改关联条件 2019/3/6 start*/ LEFT JOIN FIN_TRADE_PRODUCT H ON A.FINPROD_ID = H.FINPROD_ID LEFT JOIN PA_TRD_PRODUCT_DEAL J ON J.TRADE_ID = B.TRADE_ID WHERE 1 = 1 AND B.TRADE_STATUS='01'AND B.IS_CANCEL='N' and F.IS_SEC_BOND = 'Y' AND J.BACK_LEND_DIRECTION=#{BACK_LEND_DIRECTION_03}
AND (H.VDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD') AND TO_DATE(#{sysDate},'YYYY-MM-DD') < H.MDATE)
null) OR G.PORTFOLIO_ID IN (
